    device_address: str | None = Field(None, description="Primary device or channel address, if applicable.")
    channel_no: int | None = Field(None, description="Channel number within the device, if applicable.")
    paramset: str | None = Field(None, description="Paramset type (MASTER, VALUES, LINK), if applicable.")
