class DataPointValueChangedPayload(BaseModel):
    central: str
    interface: str | None = None
    device_address: str
    channel: int = Field(..., ge=0)
    parameter: str
    paramset_key: str = Field(..., description="VALUES, MASTER, or LINK")
    unique_id: str = Field(
        ...,
        description="Canonical loom-namespaced routing key (`loom_<routing-key>`)\nfor this data point. Always present: the daemon owns the key and a\ncentral emits no events until its CCU serial (the central-id slot of\nthe key) is resolved by the bring-up readiness gate, so the value is\nnon-empty in normal operation (an empty string would signal an\nunresolved serial). Clients consume it directly instead of rebuilding\nfrom raw fields; see docs/external-clients/ha-unique-id-migration.md.\n",
    )
    value: Any = Field(..., description="New value in its native CCU type (bool/int/float/string/list/null).")
    display_value: float | None = Field(
        None,
        description="`value` expressed in the unit the data point names, i.e.\n`value * multiplier`. Present only when that projection is\nnon-trivial; absent means `value` already is the displayable\nnumber.\n\nCarries the same meaning as `display_value` on the REST\ndata-point summary and must agree with it: a client seeds a\nreading from REST and updates it from here, so a value scaled on\none plane and raw on the other makes the reading jump on the\nfirst push. Render `display_value` when present and `value`\notherwise; writes always carry `value`, which stays the raw CCU\nwire value.\n",
    )
    previous: Any | None = Field(
        None,
        description='Prior value. Omitted when no prior value was tracked (initial\npush). Future revisions may surface a `kind: "initial"|"change"|"refresh"`\ndiscriminator on the envelope.\n',
    )
    available: bool = Field(
        ...,
        description="Whether the new value is a confirmed reading: observed AND valid\n(refreshed, paired `<param>_STATUS` acceptable, value type as\ndeclared, within the declared bounds). For a calculated data\npoint it additionally folds in the validity of every source it\nderives from.\n\nCarried on the push because it can flip without the value\nchanging — a STATUS fault does not move the reading — and\nbecause the transition *into* a fault usually arrives as a value\nchange, so a consumer reading availability only at\ncatalogue-refresh time renders the faulted value as confirmed.\nMASTER-paramset entries are always reported available:\nconfiguration is not a runtime reading.\n",
    )
    modified_at: AwareDatetime = Field(..., description="RFC3339Nano timestamp the CCU observed the change at.")
    category: str | None = Field(
        None,
        description="Model category of the data point (`switch`, `sensor`, …).\nOnly sent to clients that subscribed with `classify: true`;\nomitted otherwise.\n",
    )
    data_point_type: str | None = Field(
        None, description="North-bound type the category collapses into. Same\n`classify: true` opt-in as `category`.\n"
    )


class CustomDataPointStateChangedPayload(BaseModel):
    central: str
    device_address: str
    channel: int = Field(..., ge=0)
    name: str
    kind: str | None = Field(
        None, description="Widget hint matching CustomDPSummary.kind (e.g. `light`, `cover_blind`)."
    )
    unique_id: str = Field(
        ...,
        description="Canonical loom-namespaced routing key (`loom_<routing-key>`)\nfor this custom data point. Always present and non-empty — see\nDataPointValueChangedPayload.unique_id.\n",
    )
    state: dict[str, Any] = Field(
        ...,
        description="Composed state snapshot — keys depend on the CDP category.\n\n**Units and scales are the ones a Home Assistant client\nexpects, not the CCU's wire values.** This is the abstraction\nplane: the raw parameter values live on the data-point plane\n(`DataPointValueChangedPayload.value`, `GET\n/devices/{addr}/channels/{ch}/data-points`), where the daemon\nreports whatever the CCU sent.\n\nThe one that has caused a real mis-read: for a colour light,\n`color` is `{h, s}` with **hue in degrees 0..360 and\nsaturation 0..100** — already scaled from the wire\n`SATURATION` parameter, which carries the fraction 0..1. A\nclient that reads `color.s` and scales it again ends up with\nevery colour fully saturated. The `set_color` operation takes\nsaturation on the same 0..100 scale, so the two directions\nmatch and neither needs converting.\n",
    )


